arguments.command:
cd /tmp/vally-eval-trial-4pAUYw && mkdir -p tests/CheckoutPricing.IntegrationTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public sealed record CalculatePayableTotalRequest(string CustomerTier, decimal OrderSubtotal);

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CalculatePayableTotalRequest request) => request.OrderSubtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.IntegrationTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var handler = new CalculatePayableTotalHandler();

        var payableTotal = handler.Handle(new CalculatePayableTotalRequest("Gold", 100.00m));

        Assert.Equal(95.00m, payableTotal);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests --filter "FullyQualifiedName~S1_" --verbosity quiet 2>&1 | tail -20

